:root{
  --bg:#0b1210;
  --bg2:#101b16;
  --line:#6f8f3e;
  --text:#f2f2ed;
  --muted:#b8beb6;
  --danger:#c95b5b;
}
*{box-sizing:border-box}
html,body{
  width:100%;
  height:100%;
  margin:0;
  background:transparent;
  overflow:hidden;
  font-family:Arial,Helvetica,sans-serif;
}
.mc-widget{
  width:100%;
  padding:8px;
  transform-origin:top left;
}
.boss-row{
  display:flex;
  gap:8px;
}
.boss-card{
  position:relative;
  flex:1 1 0;
  min-width:0;
  height:122px;
  overflow:hidden;
  background:
    linear-gradient(180deg,rgba(11,18,16,.96),rgba(9,15,13,.96));
  border:1px solid rgba(111,143,62,.72);
  clip-path:polygon(8% 0,92% 0,100% 10%,100% 90%,92% 100%,8% 100%,0 90%,0 10%);
  transition:filter .25s ease,opacity .25s ease;
}
.boss-card.hidden{display:none}
.image-wrap{
  position:absolute;
  left:6px;
  right:6px;
  top:5px;
  bottom:24px;
  overflow:hidden;
  display:flex;
  align-items:center;
  justify-content:center;
  background:transparent;
}
.boss-image{
  display:block;
  width:100%;
  height:100%;
  object-fit:cover;
  object-position:center;
  mix-blend-mode:normal;
  filter:contrast(1.06) saturate(1.05);
  transform:scale(1.02);
}
.boss-name{
  position:absolute;
  left:5px;
  right:5px;
  bottom:7px;
  z-index:3;
  color:var(--text);
  font-size:9px;
  font-weight:900;
  letter-spacing:.55px;
  text-align:center;
  text-shadow:0 2px 4px rgba(0,0,0,.7);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.boss-card::after{
  content:"";
  position:absolute;
  left:20%;
  right:20%;
  bottom:2px;
  height:3px;
  border-radius:99px;
  background:rgba(162,211,68,.9);
  box-shadow:0 0 7px rgba(162,211,68,.38);
}
.boss-card.defeated{
  filter:grayscale(1);
  opacity:.42;
}
.defeated-mark{
  position:absolute;
  inset:0;
  z-index:4;
  display:none;
  align-items:center;
  justify-content:center;
  color:var(--danger);
  font-size:68px;
  text-shadow:0 3px 8px rgba(0,0,0,.75);
}
.defeated-label{
  position:absolute;
  top:7px;
  right:7px;
  z-index:5;
  display:none;
  padding:3px 5px;
  border-radius:4px;
  background:rgba(120,24,24,.82);
  color:#fff;
  font-size:7px;
  font-weight:900;
  letter-spacing:.6px;
}
.show-cross .boss-card.defeated .defeated-mark,
.boss-card.defeated .defeated-label{
  display:flex;
}
.death-pill{
  width:max-content;
  min-width:128px;
  height:31px;
  margin:8px auto 0;
  padding:0 13px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  color:var(--text);
  background:rgba(8,14,12,.94);
  border:1px solid rgba(111,143,62,.66);
  border-radius:999px;
}
.skull{
  color:var(--muted);
  font-size:14px;
}
.death-label{
  color:var(--muted);
  font-size:10px;
  font-weight:900;
  letter-spacing:.7px;
}
#death-count{
  color:#fff;
  font-size:17px;
  font-weight:950;
}

/* Responsive render refinement */
.boss-row{
  gap:10px;
}
.boss-card{
  height:clamp(132px,13vw,160px);
}
.image-wrap{
  left:8px;
  right:8px;
  top:8px;
  bottom:31px;
}
.boss-image{
  object-fit:contain;
  object-position:center;
  transform:none;
  padding:2px 4px;
}
.boss-name{
  bottom:8px;
  font-size:11px;
  letter-spacing:.7px;
}
.death-pill{
  margin-top:9px;
}

scriptTag:
(()=>{"use strict";
const unresolved=v=>typeof v==="string"&&/^\{[^{}]+\}$/.test(v.trim());
const str=(v,f="")=>v==null||unresolved(v)?f:(String(v).trim()||f);
const num=(v,f=0)=>{if(v==null||unresolved(v))return f;const n=Number(String(v).trim().replace(",","."));return Number.isFinite(n)?n:f};
const bool=(v,f=false)=>{if(typeof v==="boolean")return v;if(v==null||unresolved(v))return f;const s=String(v).trim().toLowerCase();if(["true","1","yes","on"].includes(s))return true;if(["false","0","no","off"].includes(s))return false;return f};
const clamp=(v,a,b)=>Math.min(Math.max(v,a),b);

const C={
  channel:str("{channelName}",""),
  command:str("{deathCommand}","!death").toLowerCase(),
  chatEnabled:bool("{chatEnabled}",true),
  modOnly:bool("{modOnly}",true),
  manualDeaths:Math.max(0,Math.round(num("{manualDeathCount}",0))),
  scale:clamp(num("{overlayScale}",1),.45,1.6),
  showCross:bool("{showCross}",true),
  bosses:{
    warden:{show:bool("{wardenShow}",true),dead:bool("{wardenDefeated}",false),name:str("{wardenName}","WARDEN")},
    guardian:{show:bool("{guardianShow}",true),dead:bool("{guardianDefeated}",false),name:str("{guardianName}","ELDER GUARDIAN")},
    wither:{show:bool("{witherShow}",true),dead:bool("{witherDefeated}",false),name:str("{witherName}","WITHER")},
    dragon:{show:bool("{dragonShow}",true),dead:bool("{dragonDefeated}",false),name:str("{dragonName}","ENDER DRAGON")}
  }
};

const storageKey=()=>`pogly-mc-deaths:${C.channel||"default"}`;
let deaths=C.manualDeaths;

try{
  const saved=localStorage.getItem(storageKey());
  if(saved!==null&&!isNaN(Number(saved))) deaths=Math.max(0,Math.round(Number(saved)));
}catch(_){}

const root=document.querySelector(".mc-widget");
const deathEl=document.getElementById("death-count");

function saveDeaths(){
  try{localStorage.setItem(storageKey(),String(deaths))}catch(_){}
}
function setDeaths(value){
  deaths=Math.max(0,Math.round(Number(value)||0));
  saveDeaths();
  deathEl.textContent=deaths;
}
function applyScale(){
  root.style.transform=`scale(${C.scale})`;
  root.style.width=`${100/C.scale}%`;
}
function render(){
  root.classList.toggle("show-cross",C.showCross);
  ["warden","guardian","wither","dragon"].forEach(key=>{
    const boss=C.bosses[key];
    const card=document.getElementById(`boss-${key}`);
    card.classList.toggle("hidden",!boss.show);
    card.classList.toggle("defeated",boss.dead);
    document.getElementById(`${key}-name`).textContent=boss.name;
  });
  deathEl.textContent=deaths;
}
function allowed(userstate){
  if(!C.modOnly)return true;
  return userstate?.mod===true ||
         userstate?.mod==="1" ||
         Boolean(userstate?.badges?.broadcaster);
}
function connectChat(){
  if(!C.chatEnabled || !C.channel || typeof tmi==="undefined") return;

  const client=new tmi.Client({
    connection:{secure:true,reconnect:true},
    channels:[C.channel.replace(/^#/,"")]
  });

  client.on("message",(channel,userstate,message,self)=>{
    if(self)return;
    if(String(message||"").trim().toLowerCase()!==C.command)return;
    if(!allowed(userstate))return;
    setDeaths(deaths+1);
  });

  client.connect().catch(()=>{});
  window.__minecraftBossTrackerTmi=client;
}

window.onLiveVariableUpdate=(name,value)=>{
  if(name==="manualDeathCount"){
    setDeaths(num(value,deaths));
  }else if(name==="overlayScale"){
    C.scale=clamp(num(value,C.scale),.45,1.6);
    applyScale();
  }else if(name==="showCross"){
    C.showCross=bool(value,C.showCross);
  }else if(name==="deathCommand"){
    C.command=str(value,C.command).toLowerCase();
  }else{
    const match=name.match(/^(warden|guardian|wither|dragon)(Show|Defeated|Name)$/);
    if(match){
      const boss=C.bosses[match[1]];
      if(match[2]==="Show")boss.show=bool(value,boss.show);
      if(match[2]==="Defeated")boss.dead=bool(value,boss.dead);
      if(match[2]==="Name")boss.name=str(value,boss.name);
    }
  }
  render();
};

window.minecraftDeaths={
  add:()=>setDeaths(deaths+1),
  subtract:()=>setDeaths(deaths-1),
  set:value=>setDeaths(value),
  get:()=>deaths
};

applyScale();
render();
connectChat();
})();
